package aggregate

import (
	"context"
	"errors"
	"testing"

	"github.com/steamwo/fssql/internal/core/memory"
	"github.com/steamwo/fssql/internal/core/types"
	"github.com/steamwo/fssql/internal/core/vector"
	storagetemp "github.com/steamwo/fssql/internal/storage/temp"
)

type extAggHarness struct{mm *memory.Manager;scope *memory.Scope;bm *memory.BufferManager;quotas *storagetemp.TemporaryMemoryManager;temp *storagetemp.QueryScope}
func newExtAggHarness(t testing.TB,memoryLimit,tempLimit int64)(*extAggHarness,func()){t.Helper();mm:=memory.NewManager(memoryLimit);scope:=mm.NewScope();bm:=memory.NewBufferManager(nil);quotas:=storagetemp.NewTemporaryMemoryManager(storagetemp.Limits{Global:tempLimit,DefaultResourceGroup:tempLimit,DefaultQuery:tempLimit});sm,err:=storagetemp.NewTemporaryStorageManager(t.TempDir(),quotas);if err!=nil{t.Fatal(err)};qs,err:=sm.NewQueryScope("default");if err!=nil{t.Fatal(err)};h:=&extAggHarness{mm:mm,scope:scope,bm:bm,quotas:quotas,temp:qs};cleanup:=func(){if err:=qs.Close();err!=nil{t.Fatalf("temp close: %v",err)};if err:=scope.Close();err!=nil{t.Fatalf("memory close: %v",err)};if mm.Used()!=0{t.Fatalf("memory leak=%d",mm.Used())};if quotas.GlobalUsed()!=0{t.Fatalf("temp leak=%d",quotas.GlobalUsed())}};return h,cleanup}
func consumeDataset(t testing.TB,scope *memory.Scope,bm *memory.BufferManager,consume func(*vector.DataChunk)error,rows int){t.Helper();for base:=0;base<rows;base+=256{n:=rows-base;if n>256{n=256};g,_:=vector.NewFlat(scope,bm,types.LogicalType{ID:types.BigInt},n);v,_:=vector.NewFlat(scope,bm,types.LogicalType{ID:types.BigInt},n);for i:=0;i<n;i++{g.SetInt64(i,int64((base+i)%97));v.SetInt64(i,int64(base+i+1))};c,_:=vector.NewDataChunk(g,v);if err:=consume(c);err!=nil{c.Release();t.Fatal(err)};c.Release()}}
type extAggValue struct{count int64;sum types.Int128;avg float64;min,max int64}
func collectAgg(t testing.TB,emit func(func(*vector.DataChunk)error)error)map[int64]extAggValue{t.Helper();out:=map[int64]extAggValue{};err:=emit(func(c *vector.DataChunk)error{for i:=0;i<c.Cardinality;i++{g,_:=c.Columns[0].Int64(i);cnt,_:=c.Columns[1].Int64(i);sum,_:=c.Columns[2].Int128(i);avg,_:=c.Columns[3].Float64(i);min,_:=c.Columns[4].Int64(i);max,_:=c.Columns[5].Int64(i);out[g]=extAggValue{cnt,sum,avg,min,max}};c.Release();return nil});if err!=nil{t.Fatal(err)};return out}
func TestExternalAggregateForcedSpillEqualsInMemory(t *testing.T){h,cleanup:=newExtAggHarness(t,64<<20,64<<20);defer cleanup();ts:=[]types.LogicalType{{ID:types.BigInt},{ID:types.BigInt}};specs:=[]Spec{{Kind:CountStar},{Kind:Sum,Input:1},{Kind:Avg,Input:1},{Kind:Min,Input:1},{Kind:Max,Input:1}};in,err:=NewHashAggregate(h.scope,h.bm,ts,[]int{0},specs,128);if err!=nil{t.Fatal(err)};consumeDataset(t,h.scope,h.bm,func(c *vector.DataChunk)error{return in.Consume(context.Background(),c)},4096);expected:=collectAgg(t,func(cb func(*vector.DataChunk)error)error{return in.Emit(context.Background(),cb)});in.Release();ext,err:=NewExternalAggregate(ExternalConfig{InputTypes:ts,GroupColumns:[]int{0},Specs:specs,EstimatedGroups:8,MemoryBudget:8<<10,RadixBits:4,SpillBlockBytes:2048,Scope:h.scope,Buffers:h.bm,Temp:h.temp,Compression:storagetemp.CompressionRLE});if err!=nil{t.Fatal(err)};consumeDataset(t,h.scope,h.bm,func(c *vector.DataChunk)error{return ext.Consume(context.Background(),c)},4096);actual:=collectAgg(t,func(cb func(*vector.DataChunk)error)error{return ext.Emit(context.Background(),cb)});st:=ext.Stats();if st.SpillPasses==0||st.SpilledGroups==0||st.SpillPages==0{t.Fatalf("expected spill stats %+v",st)};if len(actual)!=len(expected){t.Fatal("group count mismatch")};for k,v:=range expected{if actual[k]!=v{t.Fatalf("group %d mismatch",k)}};ext.Release();if h.temp.Used()!=0||h.temp.OwnedFiles()!=0{t.Fatalf("temp ownership used=%d files=%d",h.temp.Used(),h.temp.OwnedFiles())}}
func TestExternalAggregateTempQuotaFailureCleansUp(t *testing.T){h,cleanup:=newExtAggHarness(t,8<<20,128);defer cleanup();ext,err:=NewExternalAggregate(ExternalConfig{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.BigInt}},GroupColumns:[]int{0},Specs:[]Spec{{Kind:Sum,Input:1}},EstimatedGroups:8,MemoryBudget:1024,RadixBits:2,SpillBlockBytes:512,Scope:h.scope,Buffers:h.bm,Temp:h.temp});if err!=nil{t.Fatal(err)};failed:=false;for base:=0;base<1024&&!failed;base+=128{n:=128;g,_:=vector.NewFlat(h.scope,h.bm,types.LogicalType{ID:types.BigInt},n);v,_:=vector.NewFlat(h.scope,h.bm,types.LogicalType{ID:types.BigInt},n);for i:=0;i<n;i++{g.SetInt64(i,int64(base+i));v.SetInt64(i,1)};c,_:=vector.NewDataChunk(g,v);err=ext.Consume(context.Background(),c);c.Release();if err!=nil{failed=true}};if !failed{t.Fatal("expected temp quota failure")};ext.Release();if h.temp.Used()!=0||h.temp.OwnedFiles()!=0{t.Fatalf("temp ownership after failure used=%d files=%d",h.temp.Used(),h.temp.OwnedFiles())}}
func TestExternalAggregateCancelAfterSpillCleansUp(t *testing.T){h,cleanup:=newExtAggHarness(t,16<<20,16<<20);defer cleanup();ext,err:=NewExternalAggregate(ExternalConfig{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.BigInt}},GroupColumns:[]int{0},Specs:[]Spec{{Kind:Sum,Input:1}},EstimatedGroups:8,MemoryBudget:2048,RadixBits:3,SpillBlockBytes:512,Scope:h.scope,Buffers:h.bm,Temp:h.temp});if err!=nil{t.Fatal(err)};consumeDataset(t,h.scope,h.bm,func(c *vector.DataChunk)error{return ext.Consume(context.Background(),c)},2048);if ext.Stats().SpillPasses==0{t.Fatal("expected spill")};ctx,cancel:=context.WithCancel(context.Background());cancel();err=ext.Emit(ctx,func(c *vector.DataChunk)error{c.Release();return nil});if !errors.Is(err,context.Canceled){t.Fatalf("emit err=%v",err)};ext.Release();if h.temp.Used()!=0||h.temp.OwnedFiles()!=0{t.Fatalf("temp ownership after cancel used=%d files=%d",h.temp.Used(),h.temp.OwnedFiles())}}
func BenchmarkExternalAggregateForcedSpill(b *testing.B){for i:=0;i<b.N;i++{h,cleanup:=newExtAggHarness(b,64<<20,64<<20);ext,err:=NewExternalAggregate(ExternalConfig{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.BigInt}},GroupColumns:[]int{0},Specs:[]Spec{{Kind:Sum,Input:1}},EstimatedGroups:8,MemoryBudget:8<<10,RadixBits:4,SpillBlockBytes:4096,Scope:h.scope,Buffers:h.bm,Temp:h.temp});if err!=nil{b.Fatal(err)};consumeDataset(b,h.scope,h.bm,func(c *vector.DataChunk)error{return ext.Consume(context.Background(),c)},2048);if err:=ext.Emit(context.Background(),func(c *vector.DataChunk)error{c.Release();return nil});err!=nil{b.Fatal(err)};ext.Release();cleanup()}}
func TestExternalAggregateRecursivelyRepartitionsOversizedPartition(t *testing.T){h,cleanup:=newExtAggHarness(t,32<<20,64<<20);defer cleanup();ext,err:=NewExternalAggregate(ExternalConfig{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.BigInt}},GroupColumns:[]int{0},Specs:[]Spec{{Kind:Sum,Input:1}},EstimatedGroups:8,MemoryBudget:4<<10,RadixBits:1,MaxDepth:8,SpillBlockBytes:1024,Scope:h.scope,Buffers:h.bm,Temp:h.temp});if err!=nil{t.Fatal(err)};const rows=4096;for base:=0;base<rows;base+=256{n:=256;g,_:=vector.NewFlat(h.scope,h.bm,types.LogicalType{ID:types.BigInt},n);v,_:=vector.NewFlat(h.scope,h.bm,types.LogicalType{ID:types.BigInt},n);for i:=0;i<n;i++{g.SetInt64(i,int64(base+i));v.SetInt64(i,1)};c,_:=vector.NewDataChunk(g,v);if err:=ext.Consume(context.Background(),c);err!=nil{c.Release();t.Fatal(err)};c.Release()};seen:=0;if err:=ext.Emit(context.Background(),func(c *vector.DataChunk)error{seen+=c.Cardinality;c.Release();return nil});err!=nil{t.Fatal(err)};if seen!=rows{t.Fatalf("groups=%d want %d",seen,rows)};if ext.Stats().Repartitions==0{t.Fatalf("expected recursive repartition %+v",ext.Stats())};ext.Release();if h.temp.Used()!=0||h.temp.OwnedFiles()!=0{t.Fatalf("temp leak used=%d files=%d",h.temp.Used(),h.temp.OwnedFiles())}}
